	/**
	 * A merge join must be selected when two statement patterns share a single variable that is <em>not</em> already
	 * bound when the join is evaluated. Regression test for a bug where the merge-join decision consulted a
	 * {@code boundVars} set that had already been populated with the binding names of <em>every</em> argument in the
	 * join group, rather than only the variables bound so far at that plan position. That made the shared join key
	 * appear "already bound" and wrongly disabled merge join.
	 */
	@Test
	public void mergeJoinSelectedForSharedVariableNotBoundYet() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?a ex:p1 ?b .",
				"   ?b ex:p2 ?c .",
				"}"
		);

		SPARQLParser parser = new SPARQLParser();
		ParsedQuery q = parser.parseQuery(query, null);
		QueryJoinOptimizer opt = new QueryJoinOptimizer(new EvaluationStatistics(), new OrderedTripleSource());
		QueryRoot optRoot = new QueryRoot(q.getTupleExpr());
		opt.optimize(optRoot, null, null);

		JoinFinder joinFinder = new JoinFinder();
		optRoot.visit(joinFinder);
		Join join = joinFinder.getJoin();

		assertThat(join).as("A join must be present").isNotNull();
		assertThat(join.isMergeJoin())
				.as("Merge join must be selected for shared variable ?b, which is not bound before this join")
				.isTrue();
	}

	/**
	 * The complement of {@link #mergeJoinSelectedForSharedVariableNotBoundYet()}: when the shared join variable is
	 * already bound by a preceding join arm (here the required pattern feeding the OPTIONAL), it is not a useful merge
	 * join key and merge join must not be selected on it.
	 */
	@Test
	public void mergeJoinNotSelectedForVariableBoundByPrecedingArm() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?a ex:p0 ?b .",
				"   optional {",
				"      ?b ex:p1 ?c .",
				"      ?b ex:p2 ?d .",
				"   }",
				"}"
		);

		SPARQLParser parser = new SPARQLParser();
		ParsedQuery q = parser.parseQuery(query, null);
		QueryJoinOptimizer opt = new QueryJoinOptimizer(new EvaluationStatistics(), new OrderedTripleSource());
		QueryRoot optRoot = new QueryRoot(q.getTupleExpr());
		opt.optimize(optRoot, null, null);

		JoinFinder joinFinder = new JoinFinder();
		optRoot.visit(joinFinder);
		Join join = joinFinder.getJoin();

		assertThat(join).as("The join inside the OPTIONAL must be present").isNotNull();
		assertThat(join.isMergeJoin())
				.as("Merge join must not be selected on ?b, which is already bound by the preceding required pattern")
				.isFalse();
	}

	/**
	 * A merge join must not be selected when one of its arguments references a variable that is already bound in the
	 * enclosing scope (here {@code ?owner}, bound by the required arm of a {@code LeftJoin}). Even though the
	 * merge-join key {@code ?part} is itself not bound, the outer binding of {@code ?owner} makes the left leg
	 * ({@code ?owner ex:hasPart ?part}) selective while the right leg ({@code ?part ex:createdOn ?date}) remains a full
	 * index scan that would be re-scanned in its entirety for every incoming {@code ?owner} binding. A merge join
	 * amplifies that cost; a bound/nested-loop join that seeks the right leg per {@code ?part} is far cheaper.
	 */
	@Test
	public void mergeJoinNotSelectedWhenLegHasVariableBoundFromOutside() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?owner a ex:Owner .",
				"   optional {",
				"      ?owner ex:hasPart ?part .",
				"      ?part ex:createdOn ?date .",
				"   }",
				"}"
		);

		SPARQLParser parser = new SPARQLParser();
		ParsedQuery q = parser.parseQuery(query, null);
		QueryJoinOptimizer opt = new QueryJoinOptimizer(new EvaluationStatistics(), new OrderedTripleSource());
		QueryRoot optRoot = new QueryRoot(q.getTupleExpr());
		opt.optimize(optRoot, null, null);

		JoinFinder joinFinder = new JoinFinder();
		optRoot.visit(joinFinder);
		Join join = joinFinder.getJoin();

		assertThat(join).as("The join inside the OPTIONAL must be present").isNotNull();
		assertThat(join.isMergeJoin())
				.as("Merge join must not be selected because ?owner is bound outside the join and makes one leg "
						+ "selective while the other stays a full scan")
				.isFalse();
	}

	/**
	 * Four statement patterns that all share the same subject variable {@code ?x} and are each individually orderable
	 * by {@code ?x} must be optimized into a left-deep chain of three merge joins, all ordered on {@code ?x}. Each
	 * merge join produces output sorted by {@code ?x}, which is exactly the input the next merge join up the chain
	 * needs.
	 * <p>
	 * This exercises the merge-join chain in {@code JoinVisitor.meet(Join)}: the shared key {@code ?x} is first bound
	 * by the arguments being joined and therefore remains a valid merge-join key at every layer. It must not be treated
	 * as "already bound" simply because a lower layer of the same chain also joins on it.
	 */
	@Test
	public void mergeJoinChainedAcrossThreeLayersForSharedSubject() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?x ex:p1 ?a .",
				"   ?x ex:p2 ?b .",
				"   ?x ex:p3 ?c .",
				"   ?x ex:p4 ?d .",
				"}"
		);

		SPARQLParser parser = new SPARQLParser();
		ParsedQuery q = parser.parseQuery(query, null);
		QueryJoinOptimizer opt = new QueryJoinOptimizer(new EvaluationStatistics(), new OrderedTripleSource());
		QueryRoot optRoot = new QueryRoot(q.getTupleExpr());
		opt.optimize(optRoot, null, null);

		JoinFinder joinFinder = new JoinFinder();
		optRoot.visit(joinFinder);
		Join layer3 = joinFinder.getJoin();

		assertThat(layer3).as("A join must be present").isNotNull();

		assertThat(layer3.isMergeJoin()).as("Top join (layer 3) must be a merge join").isTrue();
		assertThat(layer3.getOrder().getName()).as("Layer 3 must be ordered on ?x").isEqualTo("x");

		assertThat(layer3.getLeftArg()).as("Layer 2 must be a join").isInstanceOf(Join.class);
		Join layer2 = (Join) layer3.getLeftArg();
		assertThat(layer2.isMergeJoin()).as("Middle join (layer 2) must be a merge join").isTrue();
		assertThat(layer2.getOrder().getName()).as("Layer 2 must be ordered on ?x").isEqualTo("x");

		assertThat(layer2.getLeftArg()).as("Layer 1 must be a join").isInstanceOf(Join.class);
		Join layer1 = (Join) layer2.getLeftArg();
		assertThat(layer1.isMergeJoin()).as("Bottom join (layer 1) must be a merge join").isTrue();
		assertThat(layer1.getOrder().getName()).as("Layer 1 must be ordered on ?x").isEqualTo("x");
	}

	/**
	 * A merge join must only be selected when both of its arguments are themselves either a {@link StatementPattern} or
	 * another merge join (checked recursively). Here the second join argument is a {@code UNION}. A
	 * {@link org.eclipse.rdf4j.query.algebra.Union} reports supported orders (it delegates to its arms), so the
	 * optimizer would otherwise be tempted to build a merge join whose right leg is the union. Merge join evaluation
	 * relies on both legs streaming sorted statement-pattern (or nested merge-join) output, so a union leg must
	 * disqualify the merge join.
	 */
	@Test
	public void mergeJoinNotSelectedWhenLegIsNotStatementPatternOrMergeJoin() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?x ex:p1 ?a .",
				"   { ?x ex:p2 ?b } union { ?x ex:p3 ?b }",
				"}"
		);

		SPARQLParser parser = new SPARQLParser();
		ParsedQuery q = parser.parseQuery(query, null);
		QueryJoinOptimizer opt = new QueryJoinOptimizer(new EvaluationStatistics(), new OrderedTripleSource());
		QueryRoot optRoot = new QueryRoot(q.getTupleExpr());
		opt.optimize(optRoot, null, null);

		JoinFinder joinFinder = new JoinFinder();
		optRoot.visit(joinFinder);
		Join join = joinFinder.getJoin();

		assertThat(join).as("A join must be present").isNotNull();
		assertThat(join.isMergeJoin())
				.as("Merge join must not be selected because one leg is a UNION, not a statement pattern or merge join")
				.isFalse();
	}

	@Test
	public void selectMergeJoinOrderReturningNullRejectsMergeJoin() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?a ex:p1 ?b .",
				"   ?b ex:p2 ?c .",
				"}"
		);

		QueryRoot defaultRoot = new QueryRoot(new SPARQLParser().parseQuery(query, null).getTupleExpr());
		new QueryJoinOptimizer(new EvaluationStatistics(), new OrderedTripleSource()).optimize(defaultRoot, null,
				null);
		assertThat(collectJoins(defaultRoot)).as("the default optimizer forms a merge join for this query")
				.anyMatch(Join::isMergeJoin);

		QueryRoot vetoRoot = new QueryRoot(new SPARQLParser().parseQuery(query, null).getTupleExpr());
		new MergeJoinOrderOptimizer(null).optimize(vetoRoot, null, null);

		assertThat(collectJoins(vetoRoot)).as("the join must still be present").isNotEmpty();
		assertThat(collectJoins(vetoRoot)).as("selectMergeJoinOrder returning null must reject merge join")
				.noneMatch(Join::isMergeJoin);
	}

	@Test
	public void selectMergeJoinOrderOverrideDeterminesJoinOrder() {
		String query = String.join("\n", "",
				"prefix ex: <ex:> ",
				"select * where {",
				"   ?a ex:p1 ?b .",
				"   ?b ex:p2 ?c .",
				"}"
		);
		QueryRoot root = new QueryRoot(new SPARQLParser().parseQuery(query, null).getTupleExpr());
		Var chosen = Var.of("b");

		new MergeJoinOrderOptimizer(chosen).optimize(root, null, null);

		List<Join> joins = collectJoins(root);
		assertThat(joins).as("a merge join must be formed").hasSize(1);
		assertThat(joins.get(0).isMergeJoin()).isTrue();
		assertThat(joins.get(0).getOrder().getName()).isEqualTo(chosen.getName());
	}

	@Test
	public void customJoinVisitorFromCreateJoinVisitorAlsoOptimizesSubselects() {
		String query = "SELECT ?s WHERE { { SELECT ?s WHERE { ?s <urn:nested-one> ?x . ?x <urn:nested-two> ?y } } "
				+ "?s <urn:outer> ?o }";
		QueryRoot root = new QueryRoot(new SPARQLParser().parseQuery(query, null).getTupleExpr());
		CostCountingOptimizer optimizer = new CostCountingOptimizer();

		optimizer.optimize(root, null, null);

		assertThat(optimizer.costedPredicates)
				.as("the subclass visitor must also cost the patterns inside the sub-select")
				.contains("urn:nested-one", "urn:nested-two", "urn:outer");
	}

	/**
	 * Optimizer whose visitor records the predicate of every statement pattern it is asked to cost.
	 */
	private static final class CostCountingOptimizer extends QueryJoinOptimizer {

		private final Set<String> costedPredicates = new HashSet<>();

		CostCountingOptimizer() {
			super(new EvaluationStatistics(), new EmptyTripleSource());
		}

		@Override
		protected JoinVisitor createJoinVisitor() {
			return new JoinVisitor() {
				@Override
				protected double getTupleExprCost(TupleExpr tupleExpr, Map<TupleExpr, Double> cardinalityMap,
						Map<TupleExpr, List<Var>> varsMap, Map<Var, Integer> varFreqMap) {
					if (tupleExpr instanceof StatementPattern) {
						costedPredicates.add(getPredicateValue(tupleExpr));
					}
					return super.getTupleExprCost(tupleExpr, cardinalityMap, varsMap, varFreqMap);
				}
			};
		}
	}

	private static List<Join> collectJoins(QueryModelNode root) {
		List<Join> joins = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				joins.add(join);
				super.meet(join);
			}
		});
		return joins;
	}

	/**
	 * Optimizer whose visitor overrides {@code selectMergeJoinOrder}: {@code null} vetoes merge join, otherwise the
	 * given variable is used as the join order.
	 */
	private static final class MergeJoinOrderOptimizer extends QueryJoinOptimizer {

		private final Var order;

		MergeJoinOrderOptimizer(Var order) {
			super(new EvaluationStatistics(), new OrderedTripleSource());
			this.order = order;
		}

		@Override
		protected JoinVisitor createJoinVisitor() {
			return new JoinVisitor() {
				@Override
				protected Var selectMergeJoinOrder(TupleExpr left, TupleExpr right, Set<Var> supportedOrders) {
					return order;
				}
			};
		}
	}

