	/**
	 * A sub-select that uses a variable internally without projecting it does not consume the VALUES variable of the
	 * same name; the VALUES block goes before the real consumer.
	 */
	@Test
	public void subselectUsingUnprojectedVariableIsNotAConsumerOfValues() {
		for (boolean supportsJoinEstimation : List.of(false, true)) {
			String query = String.join("\n", "",
					"prefix ex: <ex:> ",
					"select * where {",
					"   values ?o { ex:v ex:w }",
					"   ?s ex:pOuter ?x .",
					"   { select ?s where { ?s ex:pCheapOther ?o } }",
					"   ?s ex:pConsumer ?o .",
					"}");
			assertValuesDirectlyBeforeFirstConsumer(query, connectedPlanStatistics(supportsJoinEstimation));
		}
	}

	@Test
	public void valuesBlockSitsDirectlyBeforeConsumerThatIsAFilteredPattern() {
		for (boolean supportsJoinEstimation : List.of(false, true)) {
			assertValuesDirectlyBeforeFirstConsumer(String.join("\n", "",
					"prefix ex: <ex:> ",
					"select * where {",
					"   values ?s { ex:a ex:b }",
					"   values ?o { ex:v ex:w }",
					"   ?s ex:pCheapOther ?z .",
					"   ?s ex:pConsumer ?o2 . filter(?o2 != ?o)",
					"}"), connectedPlanStatistics(supportsJoinEstimation));
		}
	}

	private void assertValuesDirectlyBeforeFirstConsumer(String query, EvaluationStatistics statistics) {
		QueryRoot root = optimizeWith(query, statistics);
		JoinFinder finder = new JoinFinder();
		root.visit(finder);
		assertThat(finder.getJoin()).as("a join is expected in %s", root).isNotNull();
		List<TupleExpr> args = flattenJoinArgs(finder.getJoin());
		boolean checkedAny = false;
		for (int i = 0; i < args.size(); i++) {
			if (!(args.get(i) instanceof BindingSetAssignment assignment)) {
				continue;
			}
			Set<String> names = assignment.getBindingNames();
			int firstConsumer = -1;
			for (int j = 0; j < args.size(); j++) {
				if (j != i && !(args.get(j) instanceof BindingSetAssignment) && referencesAny(args.get(j), names)) {
					firstConsumer = j;
					break;
				}
			}
			if (firstConsumer < 0) {
				continue;
			}
			checkedAny = true;
			assertThat(firstConsumer).as("no consumer of %s precedes its VALUES block; args %s", names, args)
					.isGreaterThan(i);
			// Between a VALUES block and its first consumer there may only be other VALUES blocks that the same
			// consumer also reads: together they feed that one lookup. Anything else would be a real cross product.
			TupleExpr consumer = args.get(firstConsumer);
			for (int k = i + 1; k < firstConsumer; k++) {
				assertThat(args.get(k))
						.as("only VALUES blocks read by the same consumer may sit between; args %s", args)
						.isInstanceOf(BindingSetAssignment.class);
				assertThat(referencesAny(consumer, ((BindingSetAssignment) args.get(k)).getBindingNames()))
						.as("VALUES block at %d is read by the consumer at %d; args %s", k, firstConsumer, args)
						.isTrue();
			}
		}
		assertThat(checkedAny).as("at least one VALUES block has a consumer in %s", args).isTrue();
	}

	/**
	 * Whether {@code expr} reads one of {@code names}. Nested variable scopes (sub-selects, new-scope groups) only
	 * expose the names they export; variables they use internally are not visible outside.
	 */
	private static boolean referencesAny(TupleExpr expr, Set<String> names) {
		boolean[] found = { false };
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr nested && node instanceof VariableScopeChange scoped
						&& scoped.isVariableScopeChange()) {
					for (String bindingName : nested.getBindingNames()) {
						if (names.contains(bindingName)) {
							found[0] = true;
						}
					}
					return;
				}
				super.meetNode(node);
			}

			@Override
			public void meet(Var node) {
				if (!node.hasValue() && names.contains(node.getName())) {
					found[0] = true;
				}
			}
		});
		return found[0];
	}

	private static List<String> statementPredicates(TupleExpr root) {
		List<String> predicates = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				predicates.add(predicate(node));
			}
		});
		return predicates;
	}

	private static <T extends QueryModelNode> T findFirst(TupleExpr root, Class<T> type) {
		List<T> found = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (type.isInstance(node)) {
					found.add(type.cast(node));
				}
				super.meetNode(node);
			}
		});
		assertThat(found).as("expected a %s in the plan", type.getSimpleName()).isNotEmpty();
		return found.get(0);
	}

	private static EvaluationStatistics connectedPlanStatistics(boolean supportsJoinEstimation) {
		return new ConnectedPlanStatistics(supportsJoinEstimation);
	}

	/**
	 * Cardinalities chosen so that a cheap but disconnected pattern looks better than a connected one: a cross product
	 * is estimated at 1 row by the pairwise estimator and the disconnected patterns have the lowest single-pattern
	 * costs.
	 */
	private static final class ConnectedPlanStatistics extends EvaluationStatistics {

		private final boolean supportsJoinEstimation;

		private ConnectedPlanStatistics(boolean supportsJoinEstimation) {
			this.supportsJoinEstimation = supportsJoinEstimation;
		}

		@Override
		public boolean supportsJoinEstimation() {
			return supportsJoinEstimation;
		}

		@Override
		public double getCardinality(TupleExpr expr) {
			if (expr instanceof StatementPattern pattern) {
				return switch (predicate(pattern)) {
				case "ex:pA" -> 2;
				case "ex:pB" -> 1000;
				case "ex:pD" -> supportsJoinEstimation ? 100 : 2;
				case "ex:pX" -> 3;
				case "ex:pY", "ex:pExpensiveInner" -> 100;
				case "ex:pCheapInner" -> 2;
				case "ex:pFanout" -> 5000;
				case "ex:enabled" -> 1;
				case "ex:pConsumer" -> 100;
				case "ex:pCheapOther" -> 2;
				default -> 10;
				};
			}
			if (expr instanceof Join join) {
				Set<String> shared = new HashSet<>(join.getLeftArg().getBindingNames());
				shared.retainAll(join.getRightArg().getBindingNames());
				return shared.isEmpty() ? 1 : 1000;
			}
			return super.getCardinality(expr);
		}
	}

	@Override
	public QueryJoinOptimizer getOptimizer() {
		return new QueryJoinOptimizer(new EvaluationStatistics(), new EmptyTripleSource());
	}

	private TupleExpr findLeaf(TupleExpr expr) {
		if (expr instanceof UnaryTupleOperator) {
			return findLeaf(((UnaryTupleOperator) expr).getArg());
		} else if (expr instanceof BinaryTupleOperator) {
			return findLeaf(((BinaryTupleOperator) expr).getLeftArg());
		} else {
			return expr;
		}
	}

	private QueryRoot optimizeWithStandardPipeline(String query) {
		ParsedQuery parsedQuery = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
		QueryRoot root = new QueryRoot(parsedQuery.getTupleExpr());
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.optimize(root, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		return root;
	}

	private QueryRoot optimizeWith(String query, EvaluationStatistics statistics) {
		ParsedQuery parsedQuery = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
		QueryRoot root = new QueryRoot(parsedQuery.getTupleExpr());
		new QueryJoinOptimizer(statistics, new EmptyTripleSource()).optimize(root, null, null);
		return root;
	}

	private List<BindingSet> evaluateQuery(String query, TripleSource source,
			FederatedServiceResolver resolver) throws Exception {
		ParsedTupleQuery parsedQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, resolver);
		TupleExpr expression = parsedQuery.getTupleExpr();
		strategy.optimize(expression, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	private void assertServiceEndpointProducerBeforeService(String query) {
		QueryRoot root = optimizeWithStandardPipeline(query);
		EndpointOrderVisitor orderVisitor = new EndpointOrderVisitor();
		root.visit(orderVisitor);

		assertThat(orderVisitor.events).contains("service");
		assertThat(orderVisitor.events).contains("endpoint");
		assertThat(orderVisitor.events.indexOf("endpoint"))
				.as("the endpoint producer must be visited before the variable SERVICE")
				.isLessThan(orderVisitor.events.indexOf("service"));
	}

	private LeftJoin findOptional(QueryRoot root) {
		OptionalFinder optionalFinder = new OptionalFinder();
		root.visit(optionalFinder);
		assertThat(optionalFinder.leftJoin).as("expected an OPTIONAL in the optimized query").isNotNull();
		return optionalFinder.leftJoin;
	}

	private void assertOptionalValuesPrecedeStatements(LeftJoin leftJoin) {
		ValuesOrderVisitor valuesOrderVisitor = new ValuesOrderVisitor();
		leftJoin.getRightArg().visit(valuesOrderVisitor);
		assertThat(valuesOrderVisitor.events)
				.as("VALUES and its connected statement pattern; OPTIONAL RHS: " + leftJoin.getRightArg())
				.isNotEmpty();
		assertThat(valuesOrderVisitor.events.getFirst())
				.as("VALUES and its connected statement pattern; OPTIONAL RHS: " + leftJoin.getRightArg())
				.isEqualTo("values");
	}

	private List<String> optimizePriorityQuery(String query, EvaluationStatistics statistics) {
		QueryRoot root = optimizeWith(query, statistics);
		StatementFinder statementFinder = new StatementFinder();
		root.visit(statementFinder);
		return statementFinder.getStatements()
				.stream()
				.map(QueryJoinOptimizerTest::predicate)
				.filter(predicate -> predicate == null || predicate.startsWith("urn:outer"))
				.collect(Collectors.toList());
	}

	private void assertPriorityPatternsStartWithExpectedPattern(String query, EvaluationStatistics statistics,
			String expectedFirstPredicate) {
		List<String> predicates = optimizePriorityQuery(query, statistics);
		assertThat(predicates).as("outer statement-pattern order").isNotEmpty();
		assertThat(predicates.getFirst()).isEqualTo(expectedFirstPredicate);
	}

	private List<TupleExpr> flattenJoinArgs(TupleExpr expr) {
		if (expr instanceof Join join) {
			List<TupleExpr> result = new ArrayList<>();
			result.addAll(flattenJoinArgs(join.getLeftArg()));
			result.addAll(flattenJoinArgs(join.getRightArg()));
			return result;
		}
		return List.of(expr);
	}

	private TupleExpr unwrapUnaryOperators(TupleExpr expr) {
		while (expr instanceof UnaryTupleOperator unary) {
			expr = unary.getArg();
		}
		return expr;
	}

	void testOptimizer(String expectedQuery, String actualQuery)
			throws MalformedQueryException, UnsupportedQueryLanguageException {
		ParsedQuery pq = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, actualQuery, null);
		QueryJoinOptimizer opt = getOptimizer();
		QueryRoot optRoot = new QueryRoot(pq.getTupleExpr());
		opt.optimize(optRoot, null, null);

		ParsedQuery expectedParsedQuery = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, expectedQuery, null);
		QueryRoot root = new QueryRoot(expectedParsedQuery.getTupleExpr());
		assertQueryModelTrees(root, optRoot);
	}

