			if (expr instanceof StatementPattern pattern) {
				return switch (predicate(pattern)) {
				case "urn:assigned" -> 1;
				case "urn:fanout", "urn:disconnected" -> 100;
				default -> super.getCardinality(expr);
				};
			}
			if (expr instanceof Join) {
				return 10;
			}
